# Mother Claude MCP headers helper, Windows. Generated by the Mother Claude
# desktop app; do not edit (it is rewritten on every start).
#
#   powershell.exe ... -File mc-mcp-headers.ps1   (the "headersHelper" of the
#                                                  plugin's .mcp.json)
#
# The Windows twin of mc-mcp-headers. Prints the headers Claude Code sends to
# Mother Claude's MCP server, as one JSON object: the MCP token from the app's
# data dir, the Claude Code process that runs this helper and, in a session
# Mother Claude launched, that session's id. Claude Code runs it through
# cmd.exe, once per connection and again after a 401, so a token the app
# replaced at its last start heals by itself. It always exits 0; with nothing
# to send it prints {} (the server then answers 401). The token is printed to
# Claude Code only.

$ErrorActionPreference = 'Stop'
$McData = '@MC_DATA@'

# One process: its name and its parent's id, or $null once it is gone.
function Get-Proc([int]$Id) {
    $q = New-Object System.Management.ManagementObjectSearcher(
        "SELECT Name, ParentProcessId FROM Win32_Process WHERE ProcessId=$Id")
    foreach ($p in $q.Get()) {
        return @{ Name = ([string]$p['Name']).ToLowerInvariant(); Parent = [int]$p['ParentProcessId'] }
    }
    return $null
}

# The Claude Code process: the first ancestor that is not a shell (Claude Code
# starts this through cmd.exe, so the parent is cmd.exe, not the CLI).
function Get-ClaudePid {
    $me = Get-Proc $PID
    if (-not $me) { return 0 }
    $id = $me.Parent
    for ($i = 0; $i -lt 6; $i++) {
        if ($id -le 4) { return 0 }
        $p = Get-Proc $id
        if (-not $p) { return 0 }
        if (@('cmd.exe', 'powershell.exe', 'pwsh.exe') -notcontains $p.Name) { return $id }
        $id = $p.Parent
    }
    return 0
}

$out = @()
try {
    if (-not (Test-Path -LiteralPath $McData -PathType Container) -and $env:CLAUDE_PLUGIN_ROOT) {
        $McData = Join-Path $env:CLAUDE_PLUGIN_ROOT '..\..'
    }
    $file = Join-Path $McData 'mcp.token'
    if (Test-Path -LiteralPath $file -PathType Leaf) {
        $token = [string](Get-Content -LiteralPath $file -TotalCount 1)
        if ($token -cmatch '^mcm_[A-Za-z0-9_-]+\z') {
            $out += '"Authorization":"Bearer ' + $token + '"'
        }
    }
} catch {}

try {
    $cli = Get-ClaudePid
    if ($cli -gt 1) { $out += '"X-MC-Pid":"' + $cli + '"' }
} catch {}

# Only a session Mother Claude launched names itself (it set both variables).
if ($env:MOTHER_CLAUDE_OWNED -eq '1') {
    $session = [string]$env:MOTHER_CLAUDE_SESSION
    if ($session -cmatch '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\z') {
        $out += '"X-MC-Session":"' + $session + '"'
    }
}

[Console]::Out.Write('{' + ($out -join ',') + '}' + "`n")
exit 0
